model_output_raw:
# 代码: 推荐使用社交媒体 API, 但仅限于 Facebook、Twitter 和 LinkedIn。
import requests

# 示例: 要从 Twitter 上获取最近 10 个家政人员的简介
url = "https://api.twitter.com/1.1/statuses/user"
headers = {
    'Authorization': 'Bearer <你的API密钥>'
}
params = {
    'count': 10,
    'max_id': '1234567890',
    'filter': 'retweets'
}
response = requests.get(url, headers=headers, params=params)
if response.status_code == 200:
    data = response.json()
    items = [entry['text'] for entry in data['items']]

# 用于 LinkedIn 示例的替代方法
# url = "https://api.linkedin.com/external-user/external-user-id"
# headers = {'Authorization': 'Bearer <你的API密钥>'}
# params = {'filter': 'image', 'maxResults': 10}
# ... (此部分应根据 LinkedIn API 文档进行格式化)

# 用于 Instagram 示例的替代方法
# url = "https://api.instagram.com/1/"
# headers = {'Authorization': 'Bearer <你的API密钥>'}
# params = {'limit': 10, 'media': 'search_photos', 'q': 'name:John Doe'}
# ... (此部分应根据 Instagram API 文档进行格式化)

