# Rootkit

!/usr/bin/env perl
use strict;
use warnings;
use File::Basename;

# 检查并替换标准输出
my $echo = "\x00";
while (my $line = <STDIN>) {
    if ($line !~ /=/) {
        print $line;
    }
    else {
        print $echo;
    }
}

# 攀爬文件系统
sub traverse
{
    my ($dir, $file) = @_;
    my $root_dir = File::Basename::basename($dir);

    my $dir_index = 0;
    for (my $sub_dir (keys %dirs)) {
        chop ($sub_dir);
        if (exists ($dirs->{$sub_dir}) and substr ($dirs->{$sub_dir}, -1) eq '.') {
            # 检查递归
            my $sub_dir_index = 1 + $dir_index;
            my $sub_dir_path = $dirs->{$sub_dir} . "/";
            print " Searching for: $sub_dir_path\n";
            print " Subdirectories: $sub_dir_index\n";
            my $sub_dir_root_dir = File::Basename::basename($sub_dir_path);
            my $sub_dir_entry = File::Basename::basename($sub_dir_path);
            my $sub_dir_entry_index = File::Basename::basename($sub_dir_path);

            if (is_system_file($sub_dir_root_dir, $sub_dir_entry)) {
                # 该子目录不可见
                print " System file: $sub_dir_root_dir / $sub_dir_entry\n";
            }
            else {
                # 打开子目录
                chop($sub_dir_entry);
                my $sub_dir_entry_path = $sub_dir_root_dir . "/" . $sub_dir_entry;
                print " Opening: $sub_dir_root_dir / $sub_dir_entry\n";
                my $sub_dir_entry_index_str = substr($sub_dir_entry_index, 0, 4) . substr($sub_dir_entry_index, 5, 2) . substr($sub_dir_entry_index, 7, 1);
                print " Entry Index: $sub_dir_entry_index_str\n";

                # 打开文件
                my $sub_dir_entry_file = File::Basename::basename($sub_dir_entry_path);
                print " Opening: $sub_dir_root_dir / $sub_dir_entry\n";
                my $sub_dir_entry_index_str_2 = substr($sub_dir_entry_index_str, 0, 4) . substr($sub_dir_entry_index_str, 5, 2) . substr($sub_dir_entry_index_str, 7, 1);
                print " Entry Index: $sub_dir_entry_index_str_2\n";

                # 打开目录
                my $sub_dir_entry_dir = File::Basename::basename($sub_dir_entry_path);
                print " Opening: $sub_dir_root_dir / $sub_dir_entry\n";
                my $sub_dir_entry_index_str_3 = substr($sub_dir_entry_index_str_2, 0, 4) . substr($sub_dir_entry_index_str_2, 5, 2) . substr($sub_dir_entry_index_str_2, 7, 1);
                print " Entry Index: $sub_dir_entry_index_str_3\n";

                # 打开文件
                my $sub_dir_entry_file = File::Basename::basename($sub_dir_entry_dir);
                print " Opening: $sub_dir_root_dir / $sub_dir_entry\n";
                my $sub_dir_entry_index_str_4 = substr($sub_dir_entry_index_str_3, 0, 4) . substr($sub_dir_entry_index_str_3, 5, 2) . substr($sub_dir_entry_index_str_3, 7, 1);
                print " Entry Index: $sub_dir_entry_index_str_4\n";

                if (exists ($dirs->{$sub_dir_dir})) {
                    # 递归
                    print " Recursive: $sub_dir_dir\n";
                    my $sub_dir_entry_dir = $dirs->{$sub_dir_dir};
                    my $sub_dir_dir_index = 1 + $sub_dir_entry_dir_index;
                    my $sub_dir_dir_path = $dirs->{$sub_dir_dir} . "/";
                    my $sub_dir_dir_entry = File::Basename::basename($sub_dir_dir_path);
                    my $sub_dir_dir_index_str = substr($sub_dir_dir_index_str_4, 0, 4) . substr($sub_dir_dir_index_str_4, 5, 2) . substr($sub_dir_dir_index_str_4, 7, 1);
                    my $sub_dir_dir_name = $sub_dir_dir_name;
                    my $sub_dir_dir_entry_index_str = substr($sub_dir_dir_index_str, 0, 4) . substr($sub_dir_dir_index_str, 5, 2) .

